// `roadbook export mermaid` of every example, conformance chart and test chart (test/mermaid,
// regenerated by test/charts/regen.sh and checked by `cargo test`) goes through Mermaid's own
// parser and the step that turns the parse into a graph, where Mermaid refuses what its
// grammar lets through (a description on a state with states inside).

import fs from 'node:fs'
import path from 'node:path'
import { createRequire } from 'node:module'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { beforeAll, describe, expect, it } from 'vitest'

const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), 'mermaid')
const files = fs.readdirSync(dir).filter((f) => f.endsWith('.md')).sort()

/** The diagrams of an export: the body of every ```mermaid block. */
function diagrams(markdown: string): string[] {
  return [...markdown.matchAll(/^```mermaid\n([\s\S]*?)^```$/gm)].map((m) => m[1]!)
}

interface StateDb {
  extract(doc: unknown): void
  getRootDocV2(): unknown
  getData(): unknown
}
let mermaid: {
  parse(text: string): Promise<unknown>
  mermaidAPI: { getDiagramFromText(text: string): Promise<{ type: string; db: StateDb }> }
}

beforeAll(async () => {
  // Mermaid sanitizes labels with DOMPurify, which needs a DOM; Node has none. Parsing does
  // not depend on it, so the instance Mermaid imports passes text through.
  const require = createRequire(import.meta.resolve('mermaid'))
  const purifyCjs = require.resolve('dompurify')
  const purify = (await import(pathToFileURL(path.join(path.dirname(purifyCjs), 'purify.es.mjs')).href)) as { default: Record<string, unknown> }
  Object.assign(purify.default, { addHook() {}, removeHook() {}, removeHooks() {}, removeAllHooks() {}, sanitize: (s: unknown) => String(s) })
  mermaid = ((await import('mermaid')) as unknown as { default: typeof mermaid }).default
})

/** Throws Mermaid's error if it would not draw `text`. */
async function check(text: string) {
  await mermaid.parse(text)
  const d = await mermaid.mermaidAPI.getDiagramFromText(text)
  expect(d.type).toBe('stateDiagram')
  // What Mermaid's renderer does before it draws.
  d.db.extract(d.db.getRootDocV2())
  d.db.getData()
}

describe('the Mermaid export', () => {
  it('covers the examples, the conformance charts and the test charts', () => {
    for (const prefix of ['examples-', 'spec-conformance-charts-', 'packages-viewer-test-charts-']) expect(files.some((f) => f.startsWith(prefix))).toBe(true)
    expect(files).toContain('packages-viewer-test-charts-edges.md')
  })

  it('is refused by Mermaid when wrong (the check works)', async () => {
    await expect(check('stateDiagram-v2\n  [*] --> State\n')).rejects.toThrow()
    await expect(check('stateDiagram-v2\n  A: entry x\n  A: exit y\n  state A {\n    [*] --> B\n  }\n')).rejects.toThrow(/Group nodes can only have label/)
  })

  it.each(files)('%s parses in Mermaid', async (file) => {
    const md = fs.readFileSync(path.join(dir, file), 'utf8')
    const blocks = diagrams(md)
    expect(blocks.length).toBeGreaterThan(0)
    // Every block found is a whole diagram: a fence in a doc cannot open or close one.
    expect(md.match(/^```mermaid$/gm)?.length).toBe(blocks.length)
    for (const text of blocks) await check(text)
  }, 30000)
})

describe('the Mermaid export of the edge cases', () => {
  const md = () => fs.readFileSync(path.join(dir, 'packages-viewer-test-charts-edges.md'), 'utf8')
  const block = (machine: string) => diagrams(md().split(`## ${machine}\n`)[1]!)[0]!

  it('puts the rows of a container in a note, not a description', () => {
    expect(block('Rows')).toMatch(/note right of Busy\n {4}invoke work\(n\)\n {4}entry do note/)
    expect(block('Rows')).not.toMatch(/^\s*Busy:/m)
    expect(block('OnlyRoot')).toMatch(/note right of OnlyRoot_machine\n {4}entry do note\("x"\)/)
  })

  it('gives keywords and the machine ids of their own, with their names as labels', () => {
    expect(block('Note')).toContain('state "State" as State_\n')
    expect(block('Note')).toContain('ClassDef_ --> Class_: Go')
    const same = block('Same')
    expect(same).toContain('[*] --> Same_machine\n  state "Same" as Same_machine\n  state Same_machine {\n    [*] --> Same\n')
    expect(same).toContain('Same_machine --> Same: Go')
  })

  it('escapes syntax in labels', () => {
    expect(block('Rows')).toContain('note("#100;irection TB#59; a#58;#58;b #35;c#58; %% d")')
  })

  it('fences a doc so nothing in it is read as Markdown', () => {
    expect(md()).toContain('````text\nA root with rows of its own, wider than everything inside it.\n```\na fence in a doc, then <b>HTML</b> & an ending fence:\n```\n````\n')
  })
})
